/**
 * Issue #278 (owner scope addition, 2026-10-18): durably persist every
 * report generated by a scheduled run so the NextGenTP agent can surface
 * it later.
 *
 * Issue #308 (owner directive, 2026-10-18): ONE canonical copy of each
 * report, max. The generator stores the canonical copy at generation
 * time through the single seam storeReportAtGeneration() — idempotent on
 * the generation id. Every channel (UX render, email, Slack, webhook,
 * HITL dispatch) delivers THAT stored copy; no channel creates a copy,
 * and re-delivery never duplicates the row.
 *
 * Storage: the shared ORM's `mas_reports` table (DO-SQLite, same idiom
 * as mas_events). Each row carries the run/goal identity, a source
 * label, a short summary, and the full report payload as JSON — capped
 * in size so one runaway report cannot blow the 2 MB SQLite row limit.
 *
 * Retrieval: searchScheduledReports() does token-based LIKE matching
 * over title + summary + body, newest first. It is wired into the AI
 * Search agent's search path (src/agents/search.ts, src/agents/mas.ts)
 * behind the same TTL cache as upstream AI Search results, so a
 * report-backed answer is never served stale beyond the cache TTL.
 *
 * Issue #876 (production hotfix, 2026-10-21): the never-throws contract
 * stays, but persistence failures are no longer silent — the persist
 * seams (persistScheduledReportSql, storeReportAtGeneration,
 * recordUsageEvent, the ensure DDL) log the underlying SQL error via
 * console.error before returning null, and ensureScheduledReportsTable
 * reconciles every expected column additively and guards the
 * generation_id UNIQUE INDEX, so accumulated table state (duplicate
 * generation ids, a legacy column shape) can never permanently block
 * report writes for a Durable Object.
 *
 * Issue #338 (design accepted 2026-10-23): the canonical body moves to
 * R2 (reports/<reportId>.json via the REPORTS_BUCKET binding); the
 * mas_reports row keeps the metadata + search fields and gains a
 * body_r2_key pointer (NULL = body still inline). S1 lands the column
 * and the read plumbing only — writes stay inline until S2.
 *
 * Issue #2347 (#1976 step 3c, ADR 0022 D-C.3 / D-F2): the fan-out
 * contract. This fan-out is NOT a transaction candidate — its only
 * SQL write is one already-atomic INSERT, and the R2 / Vectorize /
 * AI Search legs cannot join a DO transaction; the declared
 * contract is D-C.3's cross-store shape (atomic-or-honestly-failed
 * at the seam, outcomes recorded). Every store through the ONE
 * seam now records a CanonicalReportFanoutOutcome on the row
 * (fanout_outcome column, JSON): the body leg, both index legs,
 * and a catalogued outcome code (DataFoundationCode
 * REPORT_FANOUT_STORED / _DEGRADED; a failed INSERT stores no row
 * and surfaces REPORT_FANOUT_FAILED via the logged null). The
 * divergent persistScheduledReportSql INSERT is retired into
 * this seam (see its deprecation note).
 *
 * Issue #2359 (#1976 step 4d, ADR 0022 D-A): the seam's
 * STATEMENTS moved behind the canonical-report store ports
 * (src/data/canonicalReportStorePorts.ts — the write port 3c
 * deferred, the read port, and the usage-event port for the
 * metering section below). This module keeps everything the
 * contract is made of: the fan-out logic and outcome
 * computation, the dedupe discipline, the owner refusal, the
 * never-throws shapes and every log line. The ports hold the
 * SQL — including the table DDL, whose ONE home is now the
 * write adapter's ensureSchema.
 *
 * Issue #2398: the generation UNIQUE index is tenant-scoped
 * — (user_login, generation_id) — matching this seam's
 * dedupe lookup, which was always scoped on that pair. A
 * generation id is a tenant-local idempotency key: under
 * the pre-#2398 global index, a second tenant storing a
 * report whose generation id another tenant had used missed
 * the (correctly tenant-scoped) dedupe, hit the index on
 * INSERT, and lost the report to a REPORT_FANOUT_FAILED
 * null. The adapter's ensureSchema reconciles the index
 * shape on existing tables (drop the global shape, rebuild
 * tenant-scoped; indexes only, no row moves).
 *
 * This module is SDK-free and never throws into scheduled runs: every
 * public function fails closed to null/[] on bad input or SQL errors.
 */

import type { SqlStorage } from "../orm";
import type { ScheduledReportRecord } from "../types";
import { DataFoundationCode } from "../aspects/errorCodes";
import {
  createCanonicalReportStorePorts,
  type CanonicalReportStorePorts,
} from "../data/createCanonicalReportStorePorts";
import {
  indexCanonicalReport,
  INDEX_EXCLUDED_SOURCES,
  type IndexEnv,
} from "./reportSemanticIndex";
import { indexCanonicalReportInAiSearch } from "./reportAiSearchIndex";
import { createBlobStore } from "./blobStoreR2Adapter";
import { blobText } from "./blobStorePorts";

export const SCHEDULED_REPORTS_TABLE = "mas_reports";
/** Body payload cap — keeps every row far under the SQLite row limit. */
export const SCHEDULED_REPORT_MAX_BODY_CHARS = 200_000;
export const SCHEDULED_REPORT_DEFAULT_LIMIT = 5;

export interface ScheduledReportInput {
  /** Run or goal identity, e.g. the scheduled goal id / screen timestamp. */
  runId: string;
  /**
   * Issue #308: generation identity for idempotent storage. When set,
   * storeReportAtGeneration() writes at most one row per generation id —
   * re-delivery, re-posts, and multi-channel sends never duplicate.
   * Scheduled producers use their runId; client-generated reports use a
   * content hash.
   */
  generationId?: string;
  /**
   * Owning tenant login (#584 EP-003 / multi-tenant SaaS). REQUIRED:
   * every mas_reports row belongs to exactly one user. There is no
   * "default" bucket — a write without an owner is refused (the store
   * returns null and logs why) instead of being filed under a fake
   * tenant that every scoped read would either hide or, worse, expose.
   */
  userLogin: string;
  /** Human title, e.g. "Autonomous market screen — Technology". */
  title: string;
  /** Producer label: "screener" | "iv_collection" | "retention" | ... */
  source: string;
  /** One-paragraph summary for snippet display. */
  summary: string;
  /** Full report payload (JSON-serializable). */
  body?: unknown;
  /** ISO timestamp; defaults to now. */
  createdAt?: string;
}

/** The store ports over a caller's sql handle (#2359). */
function storePorts(sql: SqlStorage): CanonicalReportStorePorts {
  return createCanonicalReportStorePorts(sql as never);
}

/**
 * Idempotent DDL for mas_reports — the write port's
 * ensureSchema is the DDL's ONE home now (#2359); this name
 * stays as the seam's ensure door for its many callers. The
 * adapter carries the #876 additive column reconciliation
 * (mas_reports has a multi-DDL history — #308, #389, #584 —
 * so a DO's table can predate any subset of the current
 * shape) and the guarded, tenant-scoped generation UNIQUE
 * index (#2398: (user_login, generation_id), shape-reconciled
 * from the pre-#2398 global index in the same ensure;
 * duplicates are logged loudly, never deleted; idempotency
 * for such a DO degrades to the SELECT-then-INSERT check in
 * storeReportAtGeneration until the rows are resolved).
 */
export function ensureScheduledReportsTable(sql: SqlStorage): void {
  storePorts(sql).write.ensureSchema();
}

/** Shape a report input into a ScheduledReportRecord (id assigned). */
export function toScheduledReportRecord(input: ScheduledReportInput): ScheduledReportRecord {
  let body = "{}";
  try {
    body = JSON.stringify(input.body ?? {});
  } catch {
    body = "{}";
  }
  if (body.length > SCHEDULED_REPORT_MAX_BODY_CHARS) {
    body = body.slice(0, SCHEDULED_REPORT_MAX_BODY_CHARS);
  }
  return {
    id: crypto.randomUUID(),
    runId: input.runId,
    generationId: input.generationId,
    title: input.title,
    source: input.source,
    summary: input.summary,
    body,
    createdAt: input.createdAt ?? new Date().toISOString(),
  };
}

export interface CanonicalStoreResult {
  /** mas_reports row id (new or pre-existing). */
  reportId: string;
  /** True when this call created the row; false on idempotent dedupe. */
  created: boolean;
  /**
   * Issue #2347: the fan-out outcome as known at return time.
   * Index legs are fire-and-forget, so an attempted leg reads
   * "pending" here; its final status lands on the report record
   * (fanout_outcome column) when the leg settles — read it back
   * with getCanonicalReportFanoutOutcome / ScheduledReportHit.
   */
  fanout: CanonicalReportFanoutOutcome;
}

/** Body-leg outcome of the fan-out (#2347). */
export type FanoutBodyStatus = "r2" | "inline" | "inline_fallback";
/** Index-leg outcome of the fan-out (#2347). */
export type FanoutIndexStatus =
  | "indexed"
  | "failed"
  | "not_attempted"
  | "pending";

/**
 * Issue #2347 (#1976 step 3c, ADR 0022 D-C.3 / D-F2.3): the
 * DECLARED outcome set of the canonical report fan-out. One
 * shape, recorded on the report record (the fanout_outcome
 * column, JSON) at insert time and updated in place as the
 * fire-and-forget index legs settle, and surfaced on the store
 * result. `outcome` names the row/body disposition; `code` is
 * the catalogued outcome code (src/aspects/errorCodes.ts,
 * DataFoundationCode) — REPORT_FANOUT_DEGRADED when any leg
 * failed or the body fell back inline, REPORT_FANOUT_STORED
 * otherwise. A failed row INSERT is the remaining member of
 * the set: it stores no row, the seam returns null, and the
 * failure is logged with REPORT_FANOUT_FAILED.
 */
export interface CanonicalReportFanoutOutcome {
  outcome: "stored_r2" | "stored_inline" | "stored_inline_fallback" | "deduped";
  code: DataFoundationCode;
  body: FanoutBodyStatus;
  vectorize: FanoutIndexStatus;
  aiSearch: FanoutIndexStatus;
  /** The AI Search executor's stable code when that leg did not index. */
  aiSearchCode?: string;
}

function fanoutCodeFor(
  body: FanoutBodyStatus,
  vectorize: FanoutIndexStatus,
  aiSearch: FanoutIndexStatus
): DataFoundationCode {
  return body === "inline_fallback" || vectorize === "failed" || aiSearch === "failed"
    ? DataFoundationCode.REPORT_FANOUT_DEGRADED
    : DataFoundationCode.REPORT_FANOUT_STORED;
}

function makeFanoutOutcome(
  outcome: CanonicalReportFanoutOutcome["outcome"],
  body: FanoutBodyStatus,
  vectorize: FanoutIndexStatus,
  aiSearch: FanoutIndexStatus,
  aiSearchCode?: string
): CanonicalReportFanoutOutcome {
  return {
    outcome,
    code: fanoutCodeFor(body, vectorize, aiSearch),
    body,
    vectorize,
    aiSearch,
    ...(aiSearchCode ? { aiSearchCode } : {}),
  };
}

/** Parse a recorded fanout_outcome value; null when absent/malformed. */
export function parseFanoutOutcome(
  raw: unknown
): CanonicalReportFanoutOutcome | null {
  try {
    if (typeof raw !== "string" || !raw) return null;
    const parsed = JSON.parse(raw) as CanonicalReportFanoutOutcome;
    if (!parsed || typeof parsed !== "object" || !parsed.outcome) return null;
    return parsed;
  } catch (err) {
    console.error(
      `[scheduledReports] parseFanoutOutcome: recorded outcome is malformed: ${err instanceof Error ? err.message : String(err)}`,
      err
    );
    return null;
  }
}

/**
 * Record (merge) leg outcomes onto a stored report row. The
 * read-modify-write is synchronous over the caller's sql
 * handle, so two legs settling in sequence cannot clobber
 * each other. Never throws (#1133 discipline): a recording
 * failure is logged with its catalog code, never dropped
 * silently and never thrown into the store's path.
 */
function recordFanoutLegOutcome(
  sql: SqlStorage,
  reportId: string,
  patch: Partial<Pick<CanonicalReportFanoutOutcome, "vectorize" | "aiSearch" | "aiSearchCode">>
): void {
  try {
    const store = storePorts(sql).write;
    const current = parseFanoutOutcome(store.getFanoutOutcomeRaw(reportId));
    if (!current) return;
    const next: CanonicalReportFanoutOutcome = { ...current, ...patch };
    next.code = fanoutCodeFor(next.body, next.vectorize, next.aiSearch);
    store.updateFanoutOutcome(reportId, JSON.stringify(next));
  } catch (err) {
    console.error(
      `[scheduledReports] recordFanoutLegOutcome failed for report ${reportId} (${DataFoundationCode.REPORT_FANOUT_DEGRADED}): ${err instanceof Error ? err.message : String(err)}`,
      err
    );
  }
}

/** The recorded fan-out outcome for a stored report, or null. Never throws. */
export function getCanonicalReportFanoutOutcome(
  sql: SqlStorage,
  reportId: string
): CanonicalReportFanoutOutcome | null {
  try {
    if (!reportId) return null;
    ensureScheduledReportsTable(sql);
    return parseFanoutOutcome(storePorts(sql).write.getFanoutOutcomeRaw(reportId));
  } catch (err) {
    console.error(
      `[scheduledReports] getCanonicalReportFanoutOutcome failed for report ${reportId}: ${err instanceof Error ? err.message : String(err)}`,
      err
    );
    return null;
  }
}

/**
 * Fire both index legs for a stored report and record each
 * leg's settled outcome on the report record (#2347). This
 * replaces the bare `void` calls: the legs stay fire-and-
 * forget for the caller, but their results are no longer
 * discarded. The Vectorize leg distinguishes attempted from
 * not-attempted by its own preconditions (bindings present +
 * source not excluded) because its boolean result conflates
 * the two; the AI Search leg's outcome code distinguishes
 * them itself ("disabled" = not attempted, per #2246).
 */
function fireFanoutIndexLegs(
  sql: SqlStorage,
  env: IndexEnv | undefined,
  vecReport: Parameters<typeof indexCanonicalReport>[1],
  aiReport: Parameters<typeof indexCanonicalReportInAiSearch>[1]
): void {
  const vectorizeAttempted =
    !!env?.AI &&
    !!env?.VECTOR_MEMORY &&
    !(INDEX_EXCLUDED_SOURCES as readonly string[]).includes(vecReport.source);
  if (!vectorizeAttempted) {
    recordFanoutLegOutcome(sql, vecReport.reportId, { vectorize: "not_attempted" });
  } else {
    void indexCanonicalReport(env, vecReport).then(
      (ok) =>
        recordFanoutLegOutcome(sql, vecReport.reportId, {
          vectorize: ok ? "indexed" : "failed",
        }),
      () =>
        recordFanoutLegOutcome(sql, vecReport.reportId, { vectorize: "failed" })
    );
  }
  void indexCanonicalReportInAiSearch(env as never, aiReport).then(
    (outcome) =>
      recordFanoutLegOutcome(sql, aiReport.reportId, {
        aiSearch: outcome.ok
          ? "indexed"
          : outcome.code === "disabled"
            ? "not_attempted"
            : "failed",
        ...(outcome.ok ? {} : { aiSearchCode: outcome.code }),
      }),
    () =>
      recordFanoutLegOutcome(sql, aiReport.reportId, {
        aiSearch: "failed",
        aiSearchCode: "upload_failed",
      })
  );
}

/** Initial index-leg statuses for a fresh/deduped store (#2347). */
function initialIndexStatuses(
  env: IndexEnv | undefined,
  source: string
): { vectorize: FanoutIndexStatus; aiSearch: FanoutIndexStatus } {
  const vectorizeAttempted =
    !!env?.AI &&
    !!env?.VECTOR_MEMORY &&
    !(INDEX_EXCLUDED_SOURCES as readonly string[]).includes(source);
  return {
    vectorize: vectorizeAttempted ? "pending" : "not_attempted",
    aiSearch: "pending",
  };
}

/**
 * Issue #308: THE single generate→store seam. The generator stores the
 * canonical report copy at generation time; every delivery channel reads
 * it back. Idempotent on input.generationId: when a row with that
 * generation id already exists, it is returned untouched (no duplicate,
 * no rewrite). SELECT-then-INSERT keeps MockSqlStorage compatible
 * (it does not parse INSERT OR REPLACE).
 *
 * Never throws: returns null on bad input or SQL errors so generation
 * and delivery are never broken by the store.
 */
/**
 * The mas_reports row id already stored for a (generation, owner) pair,
 * or "". Tenant-scoped: two tenants may legitimately produce the same
 * timestamped generation id; each owns its own row, and one tenant can
 * never be handed another's report id.
 */
function existingReportIdForGeneration(
  sql: SqlStorage,
  generationId: string,
  owner: string
): string {
  return storePorts(sql).write.findIdByGeneration(generationId, owner);
}

/**
 * Issue #1169 S4-1: the full row behind an existing report id, for the
 * redelivery index hook (a redelivery re-upserts the same vector id, so
 * the hook needs the stored title/source/summary/body, not the caller's
 * possibly-partial input). Null when the row cannot be loaded.
 */
function existingReportRowForId(
  sql: SqlStorage,
  id: string
): {
  title: string;
  source: string;
  summary: string;
  body: string;
  bodyR2Key: string | null;
} | null {
  try {
    return storePorts(sql).write.findStoredContent(id);
  } catch {
    return null;
  }
}

function generationIdOf(input: ScheduledReportInput): string | null {
  return typeof input.generationId === "string" && input.generationId
    ? input.generationId
    : null;
}

function reportOwnerOf(input: ScheduledReportInput): string {
  const owner = typeof input.userLogin === "string" ? input.userLogin.trim() : "";
  if (!owner) {
    throw new Error(
      "mas_reports requires an owning user_login — a report without a tenant cannot be stored (no \"default\" owner).",
    );
  }
  return owner;
}

/**
 * The one INSERT both store seams share — the write port's
 * insertRow (#2359); the statement itself lives in the DO
 * adapter (single line there — MockSqlStorage's INSERT regex
 * has no dotAll flag). Issue #338: when bodyR2Key is set the
 * body column stores "" and the pointer names the R2 object
 * holding the body; otherwise the body is inline and the
 * pointer is NULL.
 */
function insertScheduledReportRow(
  sql: SqlStorage,
  rec: ScheduledReportRecord,
  generationId: string | null,
  owner: string,
  bodyR2Key: string | null,
  fanout: CanonicalReportFanoutOutcome
): void {
  storePorts(sql).write.insertRow({
    id: rec.id,
    runId: rec.runId,
    title: rec.title,
    source: rec.source,
    summary: rec.summary,
    body: bodyR2Key ? "" : rec.body,
    createdAt: rec.createdAt,
    generationId,
    owner,
    bodyR2Key,
    fanoutOutcomeJson: JSON.stringify(fanout),
  });
}

/**
 * Issue #1169 S4-1: the optional env a caller passes when it has the
 * AI/Vectorize bindings — the seam then fires the index hook after a
 * successful store (fresh or redelivery). Callers without bindings omit
 * it; the hook is a silent no-op and those rows are covered by the
 * backfill route instead. The seam stays SYNC: the hook is
 * fire-and-forget (`void`), mirroring researchPublish's call.
 * Issue #2246: the same env also feeds the AI Search instance leg
 * (indexCanonicalReportInAiSearch, fired beside the Vectorize hook
 * at every site below) — inert unless AI_SEARCH_REPORT_INDEXING_ENABLED
 * is on; the fields ride the caller's env object, whose full shape
 * is the worker Env.
 */
/** Artifact fields a redelivery may backfill (issue #2528). */
export const CANONICAL_ARTIFACT_BACKFILL_FIELDS = [
  "pdfKey",
  "pdfStatus",
  "pdfError",
  "xlsxKey",
  "xlsxStatus",
  "xlsxError",
  "csvKey",
  "csvStatus",
  "csvError",
  "reportUrl",
  "scanRunId",
] as const;

/**
 * Merge missing artifact fields from a redelivery body into a stored
 * inline canonical body. Returns the merged body JSON, or null when
 * nothing was missing (or either body is not a JSON object). Only
 * fills empty/missing fields — an existing key, status, or error is
 * never overwritten, and nested `report.result` fields are filled
 * the same way when both sides carry that object.
 */
export function backfillArtifactKeys(
  storedBodyJson: string,
  redeliveryBody: unknown,
): string | null {
  let stored: Record<string, unknown>;
  try {
    const parsed: unknown = JSON.parse(storedBodyJson);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return null;
    stored = parsed as Record<string, unknown>;
  } catch {
    return null;
  }
  const incoming: Record<string, unknown> =
    redeliveryBody && typeof redeliveryBody === "object" && !Array.isArray(redeliveryBody)
      ? (redeliveryBody as Record<string, unknown>)
      : {};
  let changed = false;
  const fill = (target: Record<string, unknown>, source: Record<string, unknown>) => {
    for (const field of CANONICAL_ARTIFACT_BACKFILL_FIELDS) {
      const existing = target[field];
      const next = source[field];
      if (next === undefined || next === null || next === "") continue;
      // Monotonic per format (RCA v2b): missing fills, and a
      // failed status may upgrade to generated on a successful
      // redelivery — but a generated key/status is never
      // overwritten or downgraded by a later failed attempt.
      const statusUpgrade =
        field.endsWith("Status") && existing === "failed" && next === "generated";
      if ((existing === undefined || existing === null || existing === "") || statusUpgrade) {
        target[field] = next;
        changed = true;
      }
    }
  };
  fill(stored, incoming);
  const storedResult =
    stored.report && typeof stored.report === "object" && !Array.isArray(stored.report)
      ? (stored.report as Record<string, unknown>)
      : null;
  const incomingResult =
    incoming.report && typeof incoming.report === "object" && !Array.isArray(incoming.report)
      ? (incoming.report as Record<string, unknown>)
      : null;
  if (storedResult && incomingResult) {
    const nested = storedResult.result && typeof storedResult.result === "object" && !Array.isArray(storedResult.result)
      ? (storedResult.result as Record<string, unknown>)
      : null;
    const incomingNested = incomingResult.result && typeof incomingResult.result === "object" && !Array.isArray(incomingResult.result)
      ? (incomingResult.result as Record<string, unknown>)
      : null;
    if (nested && incomingNested) fill(nested, incomingNested);
  }
  return changed ? JSON.stringify(stored) : null;
}

export function storeReportAtGeneration(
  sql: SqlStorage,
  input: ScheduledReportInput,
  env?: IndexEnv
): CanonicalStoreResult | null {
  try {
    if (!input || typeof input.runId !== "string" || !input.runId) return null;
    const owner = reportOwnerOf(input);
    ensureScheduledReportsTable(sql);
    const generationId = generationIdOf(input);
    if (generationId) {
      const id = existingReportIdForGeneration(sql, generationId, owner);
      if (id) {
        const row = existingReportRowForId(sql, id);
        const dedupeStatuses = initialIndexStatuses(env, row?.source ?? input.source);
        const dedupedFanout = makeFanoutOutcome(
          "deduped",
          row?.bodyR2Key ? "r2" : "inline",
          dedupeStatuses.vectorize,
          dedupeStatuses.aiSearch
        );
        if (row) {
          // Issue #2528, slice 1: canonical artifact-key backfill
          // on redelivery. A keyless first write must not freeze
          // a row forever: fill ONLY fields that are missing on
          // the stored inline body, from the redelivery input.
          // Never overwrite an existing key/status, never touch
          // R2-pointer rows (their body lives in R2, not here),
          // and never fail the redelivery if the backfill fails.
          if (!row.bodyR2Key) {
            try {
              const merged = backfillArtifactKeys(row.body, input.body);
              if (merged) {
                storePorts(sql).write.updateBody(id, merged);
              }
            } catch (err) {
              console.warn(
                `[scheduledReports] storeReportAtGeneration: artifact-key backfill failed for report ${id}: ${err instanceof Error ? err.message : String(err)}`,
              );
            }
          }
          // Record the deduped outcome before re-firing the legs,
          // so the row never carries a stale pre-#2347 (absent)
          // outcome after a redelivery.
          try {
            storePorts(sql).write.updateFanoutOutcome(id, JSON.stringify(dedupedFanout));
          } catch (err) {
            console.error(
              `[scheduledReports] storeReportAtGeneration: recording the deduped fan-out outcome failed for report ${id}: ${err instanceof Error ? err.message : String(err)}`,
              err
            );
          }
          fireFanoutIndexLegs(
            sql,
            env,
            {
              reportId: id,
              title: row.title,
              source: row.source,
              summary: row.summary,
              body: row.body,
              bodyR2Key: row.bodyR2Key,
            },
            {
              reportId: id,
              title: row.title,
              source: row.source,
              summary: row.summary,
              body: row.body,
              bodyR2Key: row.bodyR2Key,
              runId: input.runId,
              ownerLogin: owner,
            }
          );
        }
        return { reportId: id, created: false, fanout: dedupedFanout };
      }
    }
    const rec = toScheduledReportRecord(input);
    const statuses = initialIndexStatuses(env, rec.source);
    const fanout = makeFanoutOutcome(
      "stored_inline",
      "inline",
      statuses.vectorize,
      statuses.aiSearch
    );
    insertScheduledReportRow(sql, rec, generationId, owner, null, fanout);
    fireFanoutIndexLegs(
      sql,
      env,
      {
        reportId: rec.id,
        title: rec.title,
        source: rec.source,
        summary: rec.summary,
        body: rec.body,
        bodyR2Key: null,
      },
      {
        reportId: rec.id,
        title: rec.title,
        source: rec.source,
        summary: rec.summary,
        body: rec.body,
        bodyR2Key: null,
        runId: rec.runId,
        ownerLogin: owner,
        storedAt: rec.createdAt,
      }
    );
    return { reportId: rec.id, created: true, fanout };
  } catch (err) {
    // Issue #876: never silent. The caller (#835's null check) can only
    // say THAT the store failed; the worker log must say WHY.
    // Issue #2347: this is the fan-out's REPORT_FANOUT_FAILED member —
    // no row was stored, so no record can carry the outcome.
    console.error(
      `[scheduledReports] storeReportAtGeneration failed for run ${typeof input?.runId === "string" ? input.runId : "?"} (${DataFoundationCode.REPORT_FANOUT_FAILED}): ${err instanceof Error ? err.message : String(err)}`,
      err
    );
    return null;
  }
}

/**
 * Issue #338 S2: the R2 write path. Same contract as
 * storeReportAtGeneration (idempotent on generation id, never throws),
 * plus: when `env.REPORTS_BUCKET` is bound, the canonical body is put to
 * R2 at reports/<reportId>.json BEFORE the row insert, and the row keeps
 * only the body_r2_key pointer (body column ""). The dedupe check runs
 * first, so a re-delivery never rewrites the R2 object. When the bucket
 * is unbound — or the put fails — the write falls back to the exact
 * legacy inline shape: a report is never lost to the storage flip.
 */
export async function storeReportAtGenerationWithR2(
  sql: SqlStorage,
  env: { REPORTS_BUCKET?: R2Bucket; AI?: any; VECTOR_MEMORY?: any },
  input: ScheduledReportInput
): Promise<CanonicalStoreResult | null> {
  try {
    if (!input || typeof input.runId !== "string" || !input.runId) return null;
    const owner = reportOwnerOf(input);
    ensureScheduledReportsTable(sql);
    const generationId = generationIdOf(input);
    if (generationId) {
      const id = existingReportIdForGeneration(sql, generationId, owner);
      if (id) {
        const row = existingReportRowForId(sql, id);
        const dedupeStatuses = initialIndexStatuses(env, row?.source ?? input.source);
        const dedupedFanout = makeFanoutOutcome(
          "deduped",
          row?.bodyR2Key ? "r2" : "inline",
          dedupeStatuses.vectorize,
          dedupeStatuses.aiSearch
        );
        if (row) {
          try {
            storePorts(sql).write.updateFanoutOutcome(id, JSON.stringify(dedupedFanout));
          } catch (err) {
            console.error(
              `[scheduledReports] storeReportAtGenerationWithR2: recording the deduped fan-out outcome failed for report ${id}: ${err instanceof Error ? err.message : String(err)}`,
              err
            );
          }
          fireFanoutIndexLegs(
            sql,
            env,
            {
              reportId: id,
              title: row.title,
              source: row.source,
              summary: row.summary,
              body: row.body,
              bodyR2Key: row.bodyR2Key,
            },
            {
              reportId: id,
              title: row.title,
              source: row.source,
              summary: row.summary,
              body: row.body,
              bodyR2Key: row.bodyR2Key,
              runId: input.runId,
              ownerLogin: owner,
            }
          );
        }
        return { reportId: id, created: false, fanout: dedupedFanout };
      }
    }
    const rec = toScheduledReportRecord(input);
    let bodyR2Key: string | null = null;
    let bodyStatus: FanoutBodyStatus = "inline";
    const store = createBlobStore(env);
    if (store) {
      const key = reportBodyR2Key(rec.id);
      try {
        await store.put(key, rec.body, {
          contentType: "application/json",
        });
        bodyR2Key = key;
        bodyStatus = "r2";
      } catch (err) {
        // Issue #2347: the fallback is now a RECORDED outcome
        // (body: "inline_fallback", code REPORT_FANOUT_DEGRADED
        // on the row), not only this log line.
        bodyStatus = "inline_fallback";
        console.error(
          `[scheduledReports] storeReportAtGenerationWithR2: R2 body put failed for report ${rec.id}; storing inline instead: ${err instanceof Error ? err.message : String(err)}`,
          err
        );
      }
    }
    const statuses = initialIndexStatuses(env, rec.source);
    const fanout = makeFanoutOutcome(
      bodyStatus === "r2"
        ? "stored_r2"
        : bodyStatus === "inline_fallback"
          ? "stored_inline_fallback"
          : "stored_inline",
      bodyStatus,
      statuses.vectorize,
      statuses.aiSearch
    );
    insertScheduledReportRow(sql, rec, generationId, owner, bodyR2Key, fanout);
    fireFanoutIndexLegs(
      sql,
      env,
      {
        reportId: rec.id,
        title: rec.title,
        source: rec.source,
        summary: rec.summary,
        body: bodyR2Key ? "" : rec.body,
        bodyR2Key,
      },
      {
        reportId: rec.id,
        title: rec.title,
        source: rec.source,
        summary: rec.summary,
        body: bodyR2Key ? "" : rec.body,
        bodyR2Key,
        runId: rec.runId,
        ownerLogin: owner,
        storedAt: rec.createdAt,
      }
    );
    return { reportId: rec.id, created: true, fanout };
  } catch (err) {
    console.error(
      `[scheduledReports] storeReportAtGenerationWithR2 failed for run ${typeof input?.runId === "string" ? input.runId : "?"} (${DataFoundationCode.REPORT_FANOUT_FAILED}): ${err instanceof Error ? err.message : String(err)}`,
      err
    );
    return null;
  }
}

/**
 * Issue #338 S3: the coupled delete — the ONLY way a mas_reports row may
 * be removed. The design requires the R2 body object to be deleted in
 * the same scope as the row, or every deletion strands an object. The
 * object delete runs first and is best-effort: if it fails (or no bucket
 * is bound) the failure is logged and the row is still deleted — a
 * stranded object is inert and is the orphan sweep's job (the design's
 * named follow-up), while a stranded ROW pointing at a deleted object
 * would break reads. mas_reports has no pruning today (retention
 * decision #786: KEEP — pruning is a product decision); this primitive
 * exists so that any future deletion path is coupled by construction.
 * Never throws; returns true when the row is gone.
 */
export async function deleteCanonicalReport(
  sql: SqlStorage,
  env: { REPORTS_BUCKET?: R2Bucket },
  reportId: string
): Promise<boolean> {
  try {
    if (!reportId) return false;
    ensureScheduledReportsTable(sql);
    const hit = getCanonicalReport(sql, reportId);
    if (!hit) return false;
    if (hit.bodyR2Key) {
      const store = createBlobStore(env);
      if (store) {
        try {
          await store.delete(hit.bodyR2Key);
        } catch (err) {
          console.error(
            `[scheduledReports] deleteCanonicalReport: R2 delete failed for report ${reportId} (key ${hit.bodyR2Key}); deleting the row anyway — the orphan sweep owns the stranded object: ${err instanceof Error ? err.message : String(err)}`,
            err
          );
        }
      } else {
        console.error(
          `[scheduledReports] deleteCanonicalReport: no REPORTS_BUCKET bound; deleting row ${reportId} strands its R2 object (key ${hit.bodyR2Key}) for the orphan sweep`
        );
      }
    }
    storePorts(sql).write.deleteRow(reportId);
    return true;
  } catch (err) {
    console.error(
      `[scheduledReports] deleteCanonicalReport failed for report ${reportId}: ${err instanceof Error ? err.message : String(err)}`,
      err
    );
    return false;
  }
}

/**
 * Issue #338 S4: resolve with lazy backfill — the design's migration
 * path ("NULL → serve inline, optionally backfill on first read"). A
 * pointer row resolves exactly as resolveCanonicalReportBody. An inline
 * row served while REPORTS_BUCKET is bound is first copied to R2 and
 * its row rewritten to the pointer shape (body "", body_r2_key set,
 * guarded on the pointer still being NULL so a racing writer wins);
 * the inline body is returned either way. Backfill is best-effort: any
 * failure is logged and the row stays inline for the next read — a
 * read never fails because the migration hiccuped.
 */
export async function resolveCanonicalReportBodyWithBackfill(
  sql: SqlStorage,
  env: { REPORTS_BUCKET?: R2Bucket },
  hit: ScheduledReportHit
): Promise<string | null> {
  if (hit.bodyR2Key) return resolveCanonicalReportBody(env, hit);
  const store = createBlobStore(env);
  if (!store || !hit.body) return hit.body;
  const key = reportBodyR2Key(hit.id);
  try {
    await store.put(key, hit.body, {
      contentType: "application/json",
    });
    ensureScheduledReportsTable(sql);
    storePorts(sql).write.backfillBodyPointer(hit.id, key);
  } catch (err) {
    console.error(
      `[scheduledReports] resolveCanonicalReportBodyWithBackfill: backfill failed for report ${hit.id}; serving inline (retried on next read): ${err instanceof Error ? err.message : String(err)}`,
      err
    );
  }
  return hit.body;
}

/**
 * Issue #338 S2: resolve a stored report's canonical body. A null pointer
 * means the body is inline — return it as-is. A set pointer reads the R2
 * object; a missing bucket, missing object, or read error resolves to
 * null so callers fail closed (delivery reports "missing") instead of
 * delivering an empty body.
 */
export async function resolveCanonicalReportBody(
  env: { REPORTS_BUCKET?: R2Bucket },
  hit: ScheduledReportHit
): Promise<string | null> {
  if (!hit.bodyR2Key) return hit.body;
  const store = createBlobStore(env);
  if (!store) return null;
  try {
    const obj = await store.get(hit.bodyR2Key);
    if (!obj) return null;
    return blobText(obj);
  } catch (err) {
    // Issue #876 doctrine: never silent — a failed body read is a
    // storage symptom the worker log must show.
    console.error(
      `[scheduledReports] resolveCanonicalReportBody failed for report ${hit.id} (key ${hit.bodyR2Key}): ${err instanceof Error ? err.message : String(err)}`,
      err
    );
    return null;
  }
}

/** Read back the canonical stored copy for delivery. Never throws. */
export function getCanonicalReport(
  sql: SqlStorage,
  reportId: string
): ScheduledReportHit | null {
  try {
    if (!reportId) return null;
    ensureScheduledReportsTable(sql);
    const r = storePorts(sql).read.getRowById(reportId);
    if (!r) return null;
    return scheduledReportHitFromRow(r as unknown as Record<string, unknown>);
  } catch {
    return null;
  }
}

/** SHA-256 hex of text — content-hash generation ids for client reports. */
export async function sha256Hex(text: string): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(text)
  );
  return Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

/**
 * Canonical JSON body for a research-report email dispatch. Field order
 * is fixed so the stored bytes are deterministic — what a channel
 * delivers equals the stored body byte-for-byte.
 */
export function canonicalResearchEmailBody(input: {
  title: string;
  fileName: string;
  attachmentBase64: string;
}): string {
  return JSON.stringify({
    title: String(input.title ?? ""),
    fileName: String(input.fileName ?? ""),
    attachmentBase64: String(input.attachmentBase64 ?? ""),
  });
}

/**
 * Canonical JSON body for a research-report webhook dispatch. Fixed
 * field order for byte-identical re-delivery from the stored copy.
 */
export function canonicalResearchWebhookBody(input: {
  title: string;
  query: string;
  sheets: Array<{ name: string; rows: Array<Record<string, unknown>> }>;
}): string {
  return JSON.stringify({
    title: String(input.title ?? ""),
    query: String(input.query ?? ""),
    sheets: Array.isArray(input.sheets) ? input.sheets : [],
  });
}

/** Parse a stored research-report body back into delivery fields. */
export function parseResearchReportBody(bodyJson: string): {
  title: string;
  fileName: string;
  attachmentBase64: string;
  query: string;
  sheets: Array<{ name: string; rows: Array<Record<string, unknown>> }>;
} | null {
  try {
    const parsed = JSON.parse(String(bodyJson)) as Record<string, unknown>;
    if (!parsed || typeof parsed !== "object") return null;
    const sheets = Array.isArray(parsed.sheets) ? parsed.sheets : [];
    return {
      title: String(parsed.title ?? ""),
      fileName: String(parsed.fileName ?? ""),
      attachmentBase64: String(parsed.attachmentBase64 ?? ""),
      query: String(parsed.query ?? ""),
      sheets: sheets as Array<{
        name: string;
        rows: Array<Record<string, unknown>>;
      }>,
    };
  } catch {
    return null;
  }
}

/**
 * Persist via raw SQL (for call sites holding SqlStorage). Never throws.
 *
 * @deprecated Superseded by storeReportAtGeneration in
 * src/services/scheduledReports.ts (the one canonical seam,
 * #2347). This name is retained for compatibility and now
 * DELEGATES to that seam: its former divergent INSERT (no
 * body_r2_key column, no index legs, no generation-id dedupe,
 * no recorded fan-out outcome) no longer exists as a separate
 * write path. Callers through this door get the full contract
 * — the shared INSERT with body_r2_key + fanout_outcome,
 * generation-id dedupe, and the recorded outcome with both
 * index legs not_attempted (this door carries no env, so no
 * leg can be attempted; the S4-1 backfill remains the repair
 * path, exactly as for any env-less canonical store).
 */
export function persistScheduledReportSql(
  sql: SqlStorage,
  input: ScheduledReportInput
): string | null {
  try {
    const stored = storeReportAtGeneration(sql, input);
    if (!stored) {
      // Issue #876: never silent — the seam has already logged
      // the underlying error; this line names THIS door so a
      // null from persistScheduledReportSql is attributable.
      console.error(
        `[scheduledReports] persistScheduledReportSql failed for run ${typeof input?.runId === "string" ? input.runId : "?"}: the canonical seam (storeReportAtGeneration) returned null; see its log line above for the underlying error`
      );
      return null;
    }
    return stored.reportId;
  } catch (err) {
    console.error(
      `[scheduledReports] persistScheduledReportSql failed for run ${typeof input?.runId === "string" ? input.runId : "?"}: ${err instanceof Error ? err.message : String(err)}`,
      err
    );
    return null;
  }
}

export interface ScheduledReportHit {
  id: string;
  runId: string;
  title: string;
  source: string;
  summary: string;
  body: string;
  createdAt: string;
  /**
   * Issue #338: R2 pointer for the canonical body, or null when the body
   * is stored inline in `body` (NULL = inline, per the accepted design).
   * S1 plumbing only — readers surface the pointer; S2 resolves it.
   */
  bodyR2Key: string | null;
  /**
   * Issue #2347: the recorded fan-out outcome for this report,
   * or null for rows stored before the contract landed (legacy
   * rows carry no outcome — never a fabricated one).
   */
  fanoutOutcome: CanonicalReportFanoutOutcome | null;
}

/**
 * Issue #338: the R2 object key for a report's canonical body, per the
 * accepted design — `reports/<reportId>.json` in the REPORTS_BUCKET
 * bucket (the `screener` bucket provisioned for #605). Content-addressed
 * by report id; bodies are immutable (regeneration = a new report id).
 */
export function reportBodyR2Key(reportId: string): string {
  return `reports/${reportId}.json`;
}

/** Map one mas_reports row to a hit, tolerating pre-#338 rows (no key). */
function scheduledReportHitFromRow(
  r: Record<string, unknown>
): ScheduledReportHit {
  const key = r.body_r2_key;
  return {
    id: String(r.id ?? ""),
    runId: String(r.run_id ?? ""),
    title: String(r.title ?? ""),
    source: String(r.source ?? ""),
    summary: String(r.summary ?? ""),
    body: String(r.body ?? ""),
    createdAt: String(r.created_at ?? ""),
    bodyR2Key: typeof key === "string" && key ? key : null,
    fanoutOutcome: parseFanoutOutcome(r.fanout_outcome),
  };
}

/**
 * Token-based search over stored reports, newest first. Tokens shorter
 * than 3 chars are ignored to keep the LIKE scan cheap. Never throws.
 */
export function searchScheduledReports(
  sql: SqlStorage,
  query: string,
  limit: number = SCHEDULED_REPORT_DEFAULT_LIMIT,
  opts?: { userLogin?: string }
): ScheduledReportHit[] {
  try {
    ensureScheduledReportsTable(sql);
    const tokens = query
      .toLowerCase()
      .split(/\s+/)
      .filter((t) => t.length > 2)
      .slice(0, 8);
    if (tokens.length === 0) return [];
    // #584 EP-003: tenant scoping. When the caller knows the user, filter
    // strictly. When unknown (undefined), preserve legacy behavior (all
    // rows): the deployment's identity strings are not yet unified
    // ("default" vs the legacy shared login vs session ids), so a strict default
    // would hide a user's own rows. See #488.
    const owner =
      opts?.userLogin && typeof opts.userLogin === "string"
        ? opts.userLogin
        : undefined;
    const capped = Math.max(1, Math.min(Math.floor(limit) || SCHEDULED_REPORT_DEFAULT_LIMIT, 25));
    // The token LIKE clause is built in the read adapter (#2359);
    // tokenization stays here as the seam's domain logic.
    const rows = storePorts(sql).read.searchRows(tokens, owner, capped);
    return rows.map((r) => scheduledReportHitFromRow(r as unknown as Record<string, unknown>));
  } catch {
    return [];
  }
}

/**
 * #584 EP-003: user-scoped report listing, newest first. Extracted from the
 * /reports route so the scoping is tested in one place.
 */
export function listScheduledReports(
  sql: SqlStorage,
  opts?: { userLogin?: string; sourceFilter?: string; limit?: number }
): ScheduledReportHit[] {
  try {
    ensureScheduledReportsTable(sql);
    // #584 EP-003: strict filter when the caller knows the user; legacy
    // unfiltered behavior when unknown (identity strings not yet unified).
    const owner =
      opts?.userLogin && typeof opts.userLogin === "string"
        ? opts.userLogin
        : undefined;
    const limit = Math.max(
      1,
      Math.min(Math.floor(opts?.limit ?? 50) || 50, 100)
    );
    const rows = storePorts(sql).read.listRows(owner, opts?.sourceFilter, limit);
    return rows.map((r) => scheduledReportHitFromRow(r as unknown as Record<string, unknown>));
  } catch {
    return [];
  }
}

/**
 * Issue #339: fetch one stored report by id for the Reports-tab detail
 * view. Owner scoping matches the list (#584 EP-003): strict when the
 * caller login is known, legacy unfiltered when it is not. Returns null
 * when the report does not exist (or is not the caller's). Never throws.
 */
export function getScheduledReportById(
  sql: SqlStorage,
  reportId: string,
  opts?: { userLogin?: string }
): ScheduledReportHit | null {
  try {
    if (!reportId || typeof reportId !== "string") return null;
    ensureScheduledReportsTable(sql);
    const owner =
      opts?.userLogin && typeof opts.userLogin === "string"
        ? opts.userLogin
        : undefined;
    const row = storePorts(sql).read.getRowByIdForOwner(reportId, owner);
    if (!row) return null;
    return scheduledReportHitFromRow(row as unknown as Record<string, unknown>);
  } catch {
    return null;
  }
}

/* ------------------------------------------------------------------ */
/* #584 EP-009: usage metering                                          */
/*                                                                      */
/* Issue #792 determination (RSI-Data C9 — parallel persistence         */
/* idioms): usage_events is ACCEPTED as the metering store of record,   */
/* a separate concern from mas_events — not a second copy of it.        */
/* mas_events is the session-scoped audit/observability log (owner:     */
/* OrchestratorAgent.recordAudit, #270; session_id / type / agent /     */
/* payload). Usage metering is tenant-scoped instead: WHO (user_login), */
/* WHAT TASK (run_id), WHAT KIND (category), with an index on           */
/* (user_login, created_at) for per-tenant listing. mas_events cannot   */
/* carry this data with its existing shape — no user_login/run_id       */
/* columns, no tenant index, and its session_id is the orchestrator     */
/* instance's session key, not a tenant identity. Writers: the          */
/* orchestrator meters completed research runs (category                */
/* "research_run") and ResearchAgent meters evaluations                 */
/* ("research_evaluation"), each into its OWN DO's database through     */
/* this module — so no single database holds a tenant's whole usage     */
/* picture, and no production reader consumes the rows yet              */
/* (listUsageEvents is exercised by tests only). Both facts are the     */
/* known price of the split; the first production usage/billing reader  */
/* must solve the placement question, and that is the trigger to        */
/* re-open consolidation. Do not add a third event log meanwhile.       */
/*                                                                      */
/* Issue #786 retention decision: usage_events is PRUNE-CLASS at 365d,   */
/* recorded in src/security/storageRetention.ts (the retention record   */
/* for every mas_* table). Implementation is deferred to the first      */
/* production reader: rows are split across two DOs' databases (this     */
/* module writes into the orchestrator's and ResearchAgent's own         */
/* storage), so a retention pass on one instance cannot prune the        */
/* other copy, and a partial prune would misstate tenant totals. Until   */
/* then the bound is one small row per research run/evaluation.          */
/* ------------------------------------------------------------------ */

export const USAGE_EVENTS_TABLE = "usage_events";

export interface UsageEventInput {
  /** Tenant identity (user login). */
  userLogin: string;
  /** Task identity, e.g. the research run id. */
  runId: string;
  /** Billable category, e.g. "research_run" | "research_evaluation". */
  category: string;
  /** Optional detail payload (JSON-serializable). */
  detail?: unknown;
}

export interface UsageEvent {
  id: string;
  userLogin: string;
  runId: string;
  category: string;
  createdAt: string;
}

/** Idempotent DDL for usage_events. Never throws. The DDL's
 *  ONE home is the usage port's ensureSchema (#2359). */
export function ensureUsageEventsTable(sql: SqlStorage): void {
  try {
    storePorts(sql).usage.ensureSchema();
  } catch (err) {
    // Fails closed; callers treat a missing table as no events. Issue
    // #876: logged, not silent (same persistence-seam rule as mas_reports).
    console.error(
      `[scheduledReports] ensureUsageEventsTable failed: ${err instanceof Error ? err.message : String(err)}`,
      err
    );
  }
}

/**
 * Record one metered consumption event, attributed to tenant + task.
 * Never throws — metering must not break the metered operation.
 */
export function recordUsageEvent(
  sql: SqlStorage,
  input: UsageEventInput
): string | null {
  try {
    if (!input || !input.userLogin || !input.runId || !input.category)
      return null;
    ensureUsageEventsTable(sql);
    const id = `use_${Date.now().toString(36)}_${Math.random()
      .toString(36)
      .slice(2, 8)}`;
    storePorts(sql).usage.insertEvent({
      id,
      userLogin: input.userLogin,
      runId: input.runId,
      category: input.category,
      createdAt: new Date().toISOString(),
      detailJson: input.detail === undefined ? null : JSON.stringify(input.detail),
    });
    return id;
  } catch (err) {
    // Issue #876: never silent at a persistence seam — metering failures
    // are logged before the never-throws null is returned.
    console.error(
      `[scheduledReports] recordUsageEvent failed for run ${typeof input?.runId === "string" ? input.runId : "?"}: ${err instanceof Error ? err.message : String(err)}`,
      err
    );
    return null;
  }
}

/** List usage events for one tenant, newest first. Never throws. */
export function listUsageEvents(
  sql: SqlStorage,
  userLogin: string,
  limit = 100
): UsageEvent[] {
  try {
    if (!userLogin) return [];
    ensureUsageEventsTable(sql);
    const capped = Math.max(1, Math.min(Math.floor(limit) || 100, 500));
    return storePorts(sql).usage.listByUser(userLogin, capped);
  } catch {
    return [];
  }
}

/**
 * #638: resolve the generated PDF download URL for a stored report.
 * The PDF bytes live in ScreenerAgent storage behind the report.pdf
 * endpoints (#269/#361); the canonical body carries either a ready
 * reportUrl or the pdfKey it was stored under. Prefers a relative
 * key-based URL (valid on any host) and falls back to the stored
 * absolute reportUrl. Returns undefined when the report has no PDF.
 * Never throws — a malformed body simply has no PDF.
 */
export function scheduledReportPdfUrl(source: string, body: unknown): string | undefined {
  try {
    const parsed: any = typeof body === "string" ? JSON.parse(body || "{}") : (body ?? {});
    const pdfKey = parsed?.pdfKey ?? parsed?.result?.pdfKey;
    if (typeof pdfKey === "string" && pdfKey) {
      if (source === "screener") return `/api/screener/report.pdf?key=${encodeURIComponent(pdfKey)}`;
      if (source === "options_scanner") return `/api/options/report.pdf?key=${encodeURIComponent(pdfKey)}`;
      // Issue #2162: strategy screens store their report under the same options
      // key families, so they serve from the same options route.
      if (source === "options_strategy") return `/api/options/report.pdf?key=${encodeURIComponent(pdfKey)}`;
      // Issue #2167: options research runs serve all three from /api/research.
      if (source === "options_research") return `/api/research/report.pdf?key=${encodeURIComponent(pdfKey)}`;
      // Issue #2180: discovery run reports serve from /api/discovery.
      if (source === "discovery") return `/api/discovery/report.pdf?key=${encodeURIComponent(pdfKey)}`;
      // Issue #1335: goal-screen PDFs serve from the goal-screen route.
      if (source === "goal_screen")
        return `/api/screening/goal-screen/report.pdf?key=${encodeURIComponent(pdfKey)}`;
    }
    const stored = parsed?.reportUrl ?? parsed?.result?.reportUrl;
    return typeof stored === "string" && stored ? stored : undefined;
  } catch {
    return undefined;
  }
}
